80	      }
81	      s.cum = cum;
82	      cum += (s.exit - (i === 0 ? s.startF : 0)) * s.length;
83	      return s;
84	    });
85	  }
86	
87	  /* Metres from (seg, f) to the first block (blockIn(seg, f) → f or null), the end of the route, or Infinity
88	     beyond `look` metres. */
89	  function blockDistance(R, seg, f, blockIn, look) {
90	    let d = 0;
91	    for (;;) {
92	      const s = R[seg];
93	      const b = blockIn(seg, f);
94	      if (b !== null && b <= s.exit) return d + Math.max(0, b - f) * s.length;
95	      d += Math.max(0, s.exit - f) * s.length;
96	      if (seg >= R.length - 1) return d;
97	      if (d > look) return Infinity;
98	      seg += 1; f = 0;
99	    }
100	  }
101	
102	  /* Move pos ({seg, f}) forward by dm metres, stopping at blocks, the route end, or an exit canLeave refuses.
103	     Returns { spans: [{seg, f0, f1, entered}], entered: [segIndex], blocked, leftover }. */
104	  function walk(R, pos, dm, blockIn, canLeave) {
105	    const spans = [], entered = [];
106	    let seg = pos.seg, f = pos.f, rem = dm, blocked = false;
107	    let span = { seg: seg, f0: f, f1: f, entered: false };
108	    spans.push(span);
109	    for (;;) {
110	      const s = R[seg];
111	      const b = blockIn(seg, f);
112	      const end = b !== null ? Math.min(b, s.exit) : s.exit;
113	      const need = Math.max(0, end - f) * s.length;
114	      if (rem < need) { f += rem / s.length; rem = 0; break; }
115	      f = Math.max(f, end); rem -= need;
116	      if (b !== null && b <= s.exit) { blocked = true; break; }
117	      if (seg >= R.length - 1 || (canLeave && !canLeave(seg))) { blocked = true; break; }
118	      if (rem <= 0) break;
119	      span.f1 = f;
120	      seg += 1; f = 0;
121	      entered.push(seg);
122	      span = { seg: seg, f0: 0, f1: 0, entered: true };
123	      spans.push(span);
124	    }
125	    span.f1 = f;
126	    pos.seg = seg; pos.f = f;
127	    return { spans: spans, entered: entered, blocked: blocked, leftover: rem };
128	  }
129	
130	  function crossed(span, f) {
131	    return (span.entered ? f >= span.f0 - 1e-9 : f > span.f0 + 1e-12) && f <= span.f1 + 1e-12;
132	  }
133	
134	  sim.route = { parse: parseRoute, blockDistance: blockDistance, walk: walk, crossed: crossed };
135	
136	  /* ---------- the race ---------- */
137	
138	  function createRace(opts) {
139	    opts = opts || {};
140	    const level = opts.level || WW.LEVEL, plates = opts.plates || WW.PLATES;
141	    const seed = opts.seed == null ? 1 : opts.seed;
142	    const L0 = level.loop || {};
143	    const T = Object.assign({}, DEFAULTS, {
144	      loopForm: L0.form || [1, 1], loopBypassJitter: L0.bypassJitter || 0, loopDropAheadF: L0.dropAheadF || 0.05
145	    }, WW.TUNING, opts.tuning || {});
146	
147	    const route = parseRoute(level, plates, 'purl');
148	    const loopRoute = parseRoute(level, plates, 'loop');
149	    if (loopRoute.length !== route.length) throw new Error('WW.sim: loopRoute must be index-aligned with route');
150	    route.forEach(function (s, i) {
151	      const l = loopRoute[i];
152	      if (l.id !== s.id || l.kind !== s.kind || l.plate !== s.plate) {
153	        throw new Error('WW.sim: loopRoute[' + i + '] (' + l.id + ') does not match route[' + i + '] (' + s.id + ')');
154	      }
155	    });
156	    const segIndex = {};
157	    route.forEach(function (s, i) { segIndex[s.id] = i; });
158	    const finishSeg = route.filter(function (s) { return s.finish !== null; })[0];
159	    if (!finishSeg) throw new Error('WW.sim: no finish event on Purl\'s route');
160	    const loopFinishSeg = loopRoute.filter(function (s) { return s.finish !== null; })[0];
161	    if (!loopFinishSeg) throw new Error('WW.sim: no finish event on Loop\'s route');
162	
163	    const ctx = {
164	      T: T, level: level, plates: plates, route: route, loopRoute: loopRoute, segIndex: segIndex,
165	      rngLoop: WW.rng(seed), rngSnag: WW.rng(((seed >>> 0) ^ 0x5bd1e995) >>> 0),
166	      heldCounter: 0, events: [], waitUntil: Infinity,
167	      inventory: sim.inventory, stitches: sim.stitches,
168	      purlTotal: finishSeg.cum + finishSeg.finish * finishSeg.length,
169	      loopTotal: loopFinishSeg.cum + loopFinishSeg.finish * loopFinishSeg.length
170	    };
171	    ctx.emit = function (ev) { ctx.events.push(ev); return ev; };
172	    ctx.message = function (text, kind, dur) {
173	      ctx.state.message = { text: text, kind: kind || 'info', until: ctx.state.time + (dur || T.messageTime) };
174	    };
175	    ctx.refreshObjective = function () { refreshObjective(ctx); };
176	
177	    // Loop's default stitch performance = Purl's animation time for that plate's stitch.
178	    loopRoute.forEach(function (seg, i) {
179	      seg.tasks.forEach(function (task) {
180	        if (task.kind !== 'stitch' || task.dur != null) return;
181	        const id = Object.keys(level.stitches || {}).filter(function (k) { return level.stitches[k].seg === route[i].id; })[0];
182	        task.dur = sim.stitches.totalTime(T, id ? (level.stitches[id].kind || id) : 'ribbon');
183	      });
184	      seg.tasks.forEach(function (task) { if (task.kind === 'stitch') task.dur += T.routeSettle; });
