283	  /* Sets state.tutorial and returns true while the first-lesson hold applies (see the header). */
284	  function tutorialHold(ctx) {
285	    const st = ctx.state, p = st.purl;
286	    let t = null;
287	    // Purl must be standing at the stop (landed, lane settled) before the world freezes around him.
288	    if (p.waitingFor && p.finishTime === null && !st.transition && !p.airborne && Math.abs(p.laneX - p.lane) < 1e-3) {
289	      const s = st.stitches[p.waitingFor];
290	      if (s && s.tutorial && s.segIndex === p.seg && !sim.stitches.passable(ctx, s.id)) {
291	        const stage = s.state === 'open' ? 'settle' : s.state === 'animating' ? 'unfurl' :
292	          (s.gripping || s.pull > 0) ? 'pull' : 'touch';
293	        t = { id: s.id, stage: stage };
294	      }
295	    }
296	    st.tutorial = t;
297	    return !!t;
298	  }
