435	  function gateBlocked(ctx) {
436	    const st = ctx.state;
437	    ctx.emit({ type: 'gate-blocked' });
438	    ctx.message(ctx.level.missingMessage || 'A THREAD IS MISSING', 'info', 2.4);
439	    const miss = sim.inventory.earliestMissing(ctx, 'purl');
440	    const toIndex = miss ? miss.segIndex : st.purl.seg;
441	    const target = ctx.route[toIndex];
442	    if (miss && miss.status === 'uncollected') miss.available = true;   // never a dead end
443	    startSpecialTransition(ctx, 'return', toIndex, target.loopReturn !== null ? target.loopReturn : 0);
