446	  function finishPurl(ctx, seg, span) {
447	    const st = ctx.state, p = st.purl;
448	    const over = (span.f1 - seg.finish) * seg.length;
449	    p.finishTime = Math.max(0, st.time - (p.speed > 0.01 ? over / p.speed : 0));
