459	  function updatePurl(ctx, dt) {
460	    const st = ctx.state, T = ctx.T, p = st.purl, R = ctx.route;
461	    stepJump(ctx, p, dt);
462	    stepLane(ctx, p, dt);
463	
464	    const tr = st.transition;
465	    if (tr && (tr.kind === 'loop' || tr.kind === 'return')) {
466	      p.speed = U.approach(p.speed, purlTarget(ctx), T.purlAccel * dt);
467	      p.distance += p.speed * dt;
468	      tr.t = Math.min(1, tr.t + dt / tr.dur);
469	      if (tr.t < 1) { p.action = tr.kind === 'loop' ? 'looping' : 'returning'; return []; }
470	      endSpecialTransition(ctx);
471	    }
472	
473	    const tangled = st.time < p.tangledUntil;
474	    const target = purlTarget(ctx);
475	    const bf = function (i, f) { return purlBlockIn(ctx, i, f); };
476	    const dB = blockDistance(R, p.seg, p.f, bf, 40);
477	    const vCap = Math.sqrt(2 * T.purlAccel * Math.max(0, dB));
478	    if (tangled) p.speed = 0;
479	    else p.speed = U.approach(p.speed, Math.min(target, vCap), T.purlAccel * dt);
480	    if (p.speed > vCap) p.speed = vCap;
481	
482	    const res = walk(R, p, p.speed * dt, bf, function (i) { return purlCanLeave(ctx, i); });
483	    p.distance += p.speed * dt - res.leftover;
484	    res.entered.forEach(function (i) { enterPurl(ctx, i); });
485	    if (R[p.seg].kind === 'connector' && st.transition) st.transition.t = p.f;
486	
487	    for (let si = 0; si < res.spans.length; si++) {
488	      const span = res.spans[si], seg = R[span.seg];
489	      seg.hints.forEach(function (h) {
490	        if (crossed(span, h.f)) st.hint = { text: h.text, until: st.time + T.hintTime };
491	      });
492	      sim.inventory.purlPickups(ctx, [span]);
493	      if (seg.finish !== null && p.finishTime === null && crossed(span, seg.finish)) {
494	        if (sim.inventory.allHeld(st, 'purl')) finishPurl(ctx, seg, span);
495	        else { gateBlocked(ctx); return res.spans.slice(0, si + 1); }
496	      }
497	    }
498	    if (p.finishTime !== null) return res.spans;
499	
500	    // recovery loop: stopped at the landing exit with a dropped thread behind
501	    const cur = R[p.seg];
502	    if (res.blocked && cur.loopReturn !== null && p.f >= cur.exit - 1e-9 && !purlCanLeave(ctx, p.seg)) {
503	      startSpecialTransition(ctx, 'loop', p.seg, cur.loopReturn);
504	      return res.spans;
505	    }
506	
507	    p.waitingFor = null;
508	    if (p.speed < 0.05) {
509	      cur.stops.forEach(function (stop) {
510	        if (Math.abs(stop.f - p.f) * cur.length < 0.05 && st.stitches[stop.stitch] &&
511	            !sim.stitches.passable(ctx, stop.stitch)) p.waitingFor = stop.stitch;
512	      });
513	    }
514	    if (tangled || p.failAt !== null) p.action = 'tangled';
515	    else if (cur.kind === 'connector') p.action = 'transition';
516	    else if (p.waitingFor) p.action = 'wait';
517	    else p.action = 'run';
518	    return res.spans;
519	  }
