532	  function settleFinish(ctx) {
533	    const st = ctx.state, p = st.purl, L = st.loop, pf = p.finishTime, lf = L.finishTime;
534	    if (pf !== null && p.rank === null) p.rank = (lf !== null && lf < pf) ? 2 : 1;
535	    if (lf !== null && L.rank === null) L.rank = (pf !== null && pf <= lf) ? 2 : 1;
536	    if (pf === null) return;
537	    if (!st.result) {
538	      st.mode = 'finished';
539	      ctx.waitUntil = pf + ctx.T.finishWaitForLoop;
540	      st.result = { purlTime: pf, loopTime: null, purlRank: p.rank, loopRank: null, winner: null, loopStillRacing: true };
541	    }
542	    const r = st.result;
543	    r.loopTime = lf;
544	    r.loopRank = L.rank;
545	    r.purlRank = p.rank;
546	    r.winner = p.rank === 1 ? 'purl' : 'loop';
