641	      },
642	      /* Make Purl immune / not immune right now (seconds from now; 0 clears). */
643	      setImmunity: function (seconds) { ctx.state.purl.immuneUntil = ctx.state.time + (seconds || 0); },
644	      forceReveal: function () { return sim.snagling.forceReveal ? sim.snagling.forceReveal(ctx) : false; },
645	      loopPlan: function () { return ctx.loopPlan; }
646	    };
647	  }
648	
649	  sim.createRace = createRace;
650	  sim.DEFAULTS = DEFAULTS;
651	})(globalThis.WW = globalThis.WW || {});
