  function deliver(ctx, owner, segIndex) {
    const out = [];
    ownItems(ctx.state, owner).forEach(function (it) {
      if (!it.available && it.segIndex === segIndex) { it.available = true; out.push(it.id); }
    });
    return out;
  }

